import json
with open('baseline-packages.json') as f: baseline = json.load(f)
with open('after-cpm-packages.json') as f: after = json.load(f)

def extract(data):
    pkgs = {}
    for proj in data.get('projects', []):
        pname = proj['path'].split('/')[-1]
        for fw in proj.get('frameworks', []):
            for pkg in fw.get('topLevelPackages', []):
                key = (pname, pkg['id'])
                pkgs[key] = pkg.get('resolvedVersion', pkg.get('requestedVersion',''))
    return pkgs

b = extract(baseline)
a = extract(after)
changes = []
for k in sorted(set(list(b.keys()) + list(a.keys()))):
    bv = b.get(k, 'N/A')
    av = a.get(k, 'N/A')
    if bv != av:
        changes.append((k[0], k[1], bv, av))
if changes:
    print('CHANGES:')
    for proj, pkg, bv, av in changes:
        print(f'  {proj} | {pkg}: {bv} -> {av}')
else:
    print('No unexpected changes (aside from intended conflict resolutions)')

# Show all resolved versions
print()
print('ALL RESOLVED:')
for k in sorted(a.keys()):
    print(f'  {k[0]} | {k[1]}: {a[k]}')
"

